Theorem tree_conservation (s : State) (i : Inputs) :
  word 130 (inputPrefix130 s i) =
  word 130 (ArrayOutput.incomingRow0 s i + ArrayOutput.incomingRow1 s i + ArrayOutput.incomingRow2 s i).
Proof.
  rewrite tree_prefix_130.
  change (word 130 (outputPrefix130 s i + 2^130 * carryColumn129 s i) = word 130 (ArrayOutput.incomingRow0 s i + ArrayOutput.incomingRow1 s i + ArrayOutput.incomingRow2 s i)).
  rewrite ArrayOutput.discard_top, tree_output_linear, tree_rows_linear; reflexivity.
Qed.
Theorem tree_output_capture (s : State) (i after : Inputs)
  (enabled : word 1 (nio_5FregEnables_5F1 i) = 1) :
  nio_5Fresult (observe (step s i) after) = word 130 (inputPrefix130 s i).
Proof. rewrite (ArrayOutput.output_capture s i after enabled); symmetry; apply tree_conservation. Qed.
Print Assumptions tree_conservation.
Print Assumptions tree_output_capture.
